ucs.kql:
let LookbackDays = 7d;
let RmmBinaries = dynamic(["anydesk.exe","screenconnect.windowsclient.exe","connectwisecontrol.client.exe","splashtop.exe","srservice.exe","pulseway.exe","fleetdeck.exe","atera.exe","syncro.exe","ninjarmmagent.exe","meshagent.exe","action1_agent.exe","tacticalrmm.exe","teamviewer.exe","rustdesk.exe","level.exe","zoho_assist_service.exe","beyondtrustremotesupport.exe"]);
let ExfilBinaries = dynamic(["rclone.exe","megasync.exe","megacmd.exe","megaclient.exe","filezilla.exe","winscp.exe"]);
let ExfilTokens = dynamic(["mega.nz","mega.co.nz","userstorage.mega.co.nz"," --config "," copy "," sync ",":mega:","remote=mega"]);
let RmmInstalls =
    DeviceProcessEvents
    | where Timestamp > ago(LookbackDays)
    | where FileName in~ (RmmBinaries) or InitiatingProcessFileName in~ (RmmBinaries)
    | where AccountName !endswith "$"
    | where AccountName !in~ ("system","local service","network service")
    | summarize RmmInstallTime = min(Timestamp), RmmBinary = any(FileName), RmmCmd = any(ProcessCommandLine)
               by DeviceId, DeviceName, AccountName;
let ExfilSignals =
    DeviceProcessEvents
    | where Timestamp > ago(LookbackDays)
    | where FileName in~ (ExfilBinaries) or ProcessCommandLine has_any (ExfilTokens)
    | project ExfilTime = Timestamp, DeviceId, ExfilBinary = FileName, ExfilCmd = ProcessCommandLine, ExfilUser = AccountName;
RmmInstalls
| join kind=inner ExfilSignals on DeviceId
| where ExfilTime between (RmmInstallTime .. RmmInstallTime + 24h)
| extend DelayMinutes = datetime_diff('minute', ExfilTime, RmmInstallTime)
| project RmmInstallTime, ExfilTime, DelayMinutes, DeviceName, AccountName, ExfilUser, RmmBinary, RmmCmd, ExfilBinary, ExfilCmd
| order by RmmInstallTime desc

